  const hs = S.ellipse(4.3 * s, -1.0 * s, 1.75 * s, 1.55 * s); P.part(hs[0], hs[1], body);
  P.dot(5.0 * s, -1.4 * s, kind === 'magpie' ? '#ffffff' : '#2a1a22');
